import Foundation

/// Which of a video's caption tracks to use: the one captions open with, and the ones a download keeps the text of.
///
/// The viewer's preferred caption language comes first, then the language of the device, then English; within a language
/// the written track wins over the auto-generated one. "en" also matches "en-US".
public enum CaptionTrackChoice {
    /// The language of the device ("de"), nil when it cannot be told.
    public static var deviceLanguage: String? {
        Locale.current.language.languageCode?.identifier
    }

    /// The track captions open with when the viewer turns them on: the first of `language`, the device language and
    /// English that the video has, else the first written track, else the first one.
    public static func preferred(
        in tracks: [CaptionTrack],
        language: String?,
        deviceLanguage: String? = CaptionTrackChoice.deviceLanguage
    ) -> CaptionTrack? {
        for candidate in [language, deviceLanguage, "en"] {
            if let candidate, !candidate.isEmpty, let track = matching(in: tracks, language: candidate) {
                return track
            }
        }
        return tracks.first(where: { !$0.isAutoGenerated }) ?? tracks.first
    }

    /// A track in `language` ("en" also matches "en-US"); a written track before an auto-generated one.
    public static func matching(in tracks: [CaptionTrack], language: String) -> CaptionTrack? {
        let wanted = baseLanguage(language)
        let matches = tracks.filter { baseLanguage($0.languageCode) == wanted }
        return matches.first(where: { !$0.isAutoGenerated }) ?? matches.first
    }

    /// The tracks whose text a download keeps, best first, at most `limit`: the track captions open with (`preferred`),
    /// then the tracks of the other languages in the order of preference, then the rest, written before auto-generated.
    /// Every track costs a request, so a video with many languages does not have them all fetched.
    public static func tracksToKeep(
        in tracks: [CaptionTrack],
        language: String?,
        deviceLanguage: String? = CaptionTrackChoice.deviceLanguage,
        limit: Int
    ) -> [CaptionTrack] {
        guard limit > 0 else { return [] }
        var ordered: [CaptionTrack] = []
        func add(_ track: CaptionTrack?) {
            if let track, !ordered.contains(where: { $0.id == track.id }) { ordered.append(track) }
        }
        add(preferred(in: tracks, language: language, deviceLanguage: deviceLanguage))
        for candidate in [language, deviceLanguage, "en"] {
            if let candidate, !candidate.isEmpty { add(matching(in: tracks, language: candidate)) }
        }
        tracks.filter { !$0.isAutoGenerated }.forEach(add)
        tracks.filter(\.isAutoGenerated).forEach(add)
        return Array(ordered.prefix(limit))
    }

    private static func baseLanguage(_ code: String) -> String {
        code.lowercased().split(whereSeparator: { $0 == "-" || $0 == "_" }).first.map(String.init) ?? code.lowercased()
    }
}
